import json,html,collections,re
from pathlib import Path
from examples import examples
E=html.escape
items=json.loads(Path('OOP/content.json').read_text())
groups=collections.OrderedDict()
for x in items: groups.setdefault(x['group'],[]).append(x)
def svg(labels,uid,green=False):
 h=90*len(labels)+15
 color='#245b48' if green else '#8e7765'
 s=f'<svg viewBox="0 0 380 {h}" role="img" aria-labelledby="{uid}"><title id="{uid}">{E(" → ".join(labels))}</title><defs><marker id="arrow-{uid}" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0 L8 4 L0 8" fill="none" stroke="{color}"/></marker></defs>'
 for i,label in enumerate(labels):
  y=10+i*90
  if i:s+=f'<path d="M190 {y-25} V{y-3}" stroke="{color}" stroke-width="2" marker-end="url(#arrow-{uid})"/>'
  s+=f'<rect x="12" y="{y}" width="356" height="64" rx="12" fill="{ "#f8fcf1" if green else "#f8f3ec"}" stroke="{color}" stroke-width="1.3"/>'
  # Korean labels fit a max of 22 characters at 17px within this width.
  size=17 if len(label)<24 else 14
  s+=f'<text x="190" y="{y+39}" text-anchor="middle" fill="#243e3b" font-size="{size}" font-family="system-ui,sans-serif">{E(label)}</text>'
 return s+'</svg>'
hero='''<svg class="hero-visual" viewBox="0 0 440 350" role="img" aria-label="하나의 거대한 코드를 데이터, 행동, 협력이라는 세 책임으로 나눈 개념도"><rect x="20" y="20" width="400" height="310" rx="35" fill="#e9eddf"/><g stroke="#719181" stroke-width="2" fill="none"><path d="M220 103V155M90 155H350M90 155V195M220 155V195M350 155V195"/></g><rect x="123" y="45" width="194" height="65" rx="15" fill="#245b48"/><text x="220" y="86" text-anchor="middle" font-size="22" fill="#fffef9" font-family="system-ui">좋은 객체 설계</text><g fill="#fffef9" stroke="#b9c7b1"><rect x="37" y="190" width="107" height="94" rx="15"/><rect x="166" y="190" width="107" height="94" rx="15"/><rect x="296" y="190" width="107" height="94" rx="15"/></g><g font-family="system-ui" text-anchor="middle" fill="#245b48"><text x="90" y="229" font-size="27">{ }</text><text x="220" y="229" font-size="27">ƒ()</text><text x="350" y="229" font-size="27">↔</text><text x="90" y="263" font-size="18">데이터</text><text x="220" y="263" font-size="18">행동</text><text x="350" y="263" font-size="18">협력</text></g></svg>'''
nav=''.join(f'<details {"open" if i==0 else ""}><summary>{E(g)} <small>{len(xs)}개 개념</small></summary>'+''.join(f'<a href="#{x["id"]}" data-lesson="{x["id"]}"><span class="check"></span>{E(x["ko"])}<small>{E(x["en"])}</small></a>' for x in xs)+'</details>' for i,(g,xs) in enumerate(groups.items()))
intro={ 'OOP 기초':'객체, 책임, 인터페이스부터 차근차근. 패턴을 읽기 위한 언어를 익혀요.','SOLID':'변경에 강한 설계의 다섯 가지 관점. 원칙을 적용할 이유와 한계를 함께 봐요.','생성 패턴':'무엇을 누가 어떻게 만들까요? 객체 생성의 책임을 정리해요.','구조 패턴':'객체들을 어떻게 연결할까요? 감싸고, 묶고, 인터페이스를 맞춰요.','행동 패턴':'누가 어떤 일을 할까요? 알고리즘과 상태, 메시지의 책임을 나눠요.','코드 스멜':'코드가 보내는 변경의 신호. 문제가 있는지 먼저 판단해요.'}
cards=''.join(f'<a class="card" href="#{xs[0]["id"]}"><span class="chapter-number">{i+1:02}</span><h3>{E(g)} ↗</h3><p>{E(intro.get(g,"작은 구조 변경을 전후 도식으로 비교하고, 적용할 때의 주의점을 살펴봐요."))}</p><small>{len(xs)}개 항목 · 하나씩 읽기</small></a>' for i,(g,xs) in enumerate(groups.items()))
articles=[]
for i,x in enumerate(items):
 id=x['id'];pattern='패턴' in x['group']; basic=x['group'] in ['OOP 기초','SOLID']
 before_title='먼저 떠올릴 상황' if basic else '해결하려는 상황'
 after_title='핵심 관점' if basic else '구조를 바꾼 뒤'
 source='https://refactoring.guru/design-patterns/catalog' if pattern else 'https://refactoring.guru/refactoring/catalog'
 if basic:source='https://refactoring.guru/design-patterns/what-is-pattern'
 code=f'<section><div class="code-head"><h2>Python으로 읽어 보기</h2><button class="copy">코드 복사</button></div><p class="legend">구조를 보여 주는 독립 실행 예제예요. Python 3에서 실행할 수 있어요.</p><pre><code>{E(examples[id])}</code></pre></section>' if id in examples else ''
 articles.append(f'''<article class="lesson" id="{id}" data-title="{E(x['ko'])}" hidden><div class="lesson-head"><span class="eyebrow">{E(x['group'])} / {i+1:03}</span><h1 tabindex="-1">{E(x['ko'])}</h1><div class="english">{E(x['en'])}</div></div><section><h2>한 문장으로 이해하기</h2><p class="concept">{E(x['idea'])}</p></section><section class="example"><span class="eyebrow">가까운 예시</span><p>{E(x['example'])}</p></section><section><h2>그림으로 연결하기</h2><div class="diagram-grid"><div class="diagram-panel"><h3>01 · {before_title}</h3>{svg(x['before'],id+'-before')}</div><div class="diagram-panel after"><h3>02 · {after_title}</h3>{svg(x['after'],id+'-after',True)}</div></div><p class="diagram-caption">화살표는 위에서 아래로 개념을 읽는 순서예요. 정확한 UML 관계나 실제 실행 순서를 뜻하지는 않아요.</p></section>{code}<section class="caution"><h2>여기서 헷갈리지 않기</h2><p>{E(x['caution'])}</p></section><section><h2>내 코드에 대입해 보기</h2><p>예시의 객체를 내 프로젝트의 객체로 바꿔 보세요. 어떤 책임이 한곳에 몰려 있고, 무엇이 바뀔 때 다른 코드까지 수정해야 하나요?</p><details><summary>점검 순서 펼치기</summary><ol><li>현재 입력과 결과, 실패 시 동작을 적어요.</li><li>위 도식처럼 책임이나 표현을 한 단계만 바꿔요.</li><li>기존 동작이 유지되는지 확인하고 복잡도가 줄었는지 비교해요.</li></ol></details></section><div class="finish"><button class="done" data-id="{id}" aria-pressed="false">이해했어요 · 학습 완료</button><a href="#{items[i-1]['id'] if i else 'overview'}">← 이전</a><a href="#{items[i+1]['id'] if i+1<len(items) else 'overview'}">{'다음 개념 →' if i+1<len(items) else '전체 목차 →'}</a></div><p class="legend">더 읽기: <a href="{source}" target="_blank" rel="noopener">Refactoring Guru의 관련 목차 ↗</a></p></article>''')
page=f'''<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#245b48"><meta name="description" content="한국어로 쉽게 배우는 OOP, SOLID, 디자인 패턴, 코드 스멜과 리팩터링. 126개 개념, 252개 전후 도식과 Python 예제."><title>OOP 도감 · 그림으로 배우는 객체지향</title><link rel="stylesheet" href="./style.css"><script defer src="./app.js"></script><noscript><style>.lesson[hidden]{{display:block!important}}aside{{display:block}}.done,.copy{{display:none}}</style></noscript></head><body><a class="skip" href="#main">본문으로 이동</a><header><a href="#overview"><span class="logo">O</span><strong>OOP 도감</strong></a><nav class="header-links" aria-label="사이트 메뉴"><a href="/">Seonwoo의 홈 ↗</a><a href="/oop-cafe/">OOP Café ↗</a><a href="#overview">전체 목차</a></nav></header><button id="menu" class="mobile-toggle" aria-controls="sidebar" aria-expanded="false">☰ 개념 찾기 / 목차</button><div class="layout"><aside id="sidebar" aria-label="개념 목차"><a class="overview-link" href="#overview">↖ 학습 지도</a><label for="search">궁금한 개념 찾기</label><input id="search" type="search" placeholder="전략, 상속, Factory…" autocomplete="off"><p id="search-result" class="no-results" role="status"></p><div class="progress"><p id="progress-text">0 / {len(items)}개 학습 완료</p><progress max="{len(items)}" value="0" aria-label="학습 진도"></progress><small>이 브라우저에 진도가 저장돼요.</small><p id="save-status" role="status"></p></div>{nav}</aside><main id="main" class="main"><div id="overview"><div class="hero"><div><span class="eyebrow">SEONWOO'S LEARNING NOTES · 01</span><h1>객체지향,<br>그림으로 이해해요.</h1><p class="lead">어려운 용어를 외우기 전에,<br>왜 필요한지부터 알아보는 작은 설계 도감.</p><p><span class="badge">쉬운 한국어</span> <span class="badge">전후 비교 도식</span></p><a class="primary" href="#class-and-object">클래스와 객체부터 시작 →</a></div>{hero}</div><div class="numbers"><div><strong>126</strong><span>한 번에 하나씩, 개념</span></div><div><strong>252</strong><span>전후 비교 도식</span></div><div><strong>{len(examples)}</strong><span>Python 예제</span></div></div><div class="section-head"><h2>어디부터 읽어 볼까요?</h2><span class="eyebrow">LEARNING MAP</span></div><p class="legend">처음이라면 기초 → SOLID → 패턴 순서로, 코드를 정리하고 싶다면 코드 스멜 → 리팩터링 기법 순서로 읽어 보세요.</p><div class="grid">{cards}</div><div class="note"><strong>도감 사용법</strong><p>왼쪽 검색으로 한국어·영문 이름과 설명을 찾을 수 있어요. 개념을 읽은 뒤 ‘학습 완료’를 누르면 진도가 저장됩니다. 각 개념의 주소는 그대로 공유할 수 있어요.</p></div><section class="all-lessons"><h2>참고 자료와 범위</h2><p>Refactoring Guru의 공개 주제 목록을 길잡이로 삼아, 설명·예시·도식을 독립적으로 작성한 한국어 학습 노트예요. 원문의 번역본이나 공식 자료는 아니며, 유료 책·강의 내용은 포함하지 않아요.</p><p>OOP 기초 10개, SOLID 5개, 공개 디자인 패턴 22개, 코드 스멜 23개, 리팩터링 기법 66개를 다룹니다. 생성·구조·행동 패턴 전 항목에는 Python 예제가 있어요.</p><a href="https://refactoring.guru/design-patterns/catalog" target="_blank" rel="noopener">디자인 패턴 원문 목차 ↗</a><a href="https://refactoring.guru/refactoring/catalog" target="_blank" rel="noopener">리팩터링 원문 목차 ↗</a></section></div>{''.join(articles)}<footer>Seonwoo's OOP Atlas · 독립적으로 작성한 학습 노트 · 2026.11<br>패턴은 목표가 아니라 도구예요. 지금 해결할 문제가 있을 때 작게 적용해 보세요.</footer></main></div></body></html>'''
